Here is the commit message:
libbpf: Fix realloc usage in bpf_core_find_cands

Fix bug requesting invalid size of reallocated array when constructing CO-RE
relocation candidate list. This can cause problems if there are many potential
candidates and a very fine-grained memory allocator bucket sizes are used.

Fixes: ddc7c3042614 ("libbpf: implement BPF CO-RE offset relocation algorithm")
Reported-by: William Smith <williampsmith@fb.com>
Signed-off-by: Andrii Nakryiko <andriin@fb.com>
Signed-off-by: Daniel Borkmann <daniel@iogearbox.net>
Acked-by: Yonghong Song <yhs@fb.com>
Link: https://lore.kernel.org/bpf/20200124201847.212528-1-andriin@fb.com

Here is the root cause:
The bug arises from the incorrect usage of `realloc`, which does not account for the size of each element when resizing the array. This can lead to requesting an invalid size for the reallocated memory, especially when there are many potential candidates, resulting in memory allocation issues. The use of `reallocarray` corrects this by ensuring the total size is calculated as the number of elements multiplied by the size of each element, thus preventing potential memory corruption or allocation failures.

Here is the patch:

 static struct ids_vec *bpf_core_find_cands(const struct btf *local_btf,
 					   __u32 local_type_id,
 					   const struct btf *targ_btf)
 {
 	size_t local_essent_len, targ_essent_len;
 	const char *local_name, *targ_name;
 	const struct btf_type *t;
 	struct ids_vec *cand_ids;
 	__u32 *new_ids;
 	int i, err, n;

 	t = btf__type_by_id(local_btf, local_type_id);
 	if (!t)
 		return ERR_PTR(-EINVAL);

 	local_name = btf__name_by_offset(local_btf, t->name_off);
 	if (str_is_empty(local_name))
 		return ERR_PTR(-EINVAL);
 	local_essent_len = bpf_core_essential_name_len(local_name);

 	cand_ids = calloc(1, sizeof(*cand_ids));
 	if (!cand_ids)
 		return ERR_PTR(-ENOMEM);

 	n = btf__get_nr_types(targ_btf);
 	for (i = 1; i <= n; i++) {
 		t = btf__type_by_id(targ_btf, i);
 		targ_name = btf__name_by_offset(targ_btf, t->name_off);
 		if (str_is_empty(targ_name))
 			continue;

 		targ_essent_len = bpf_core_essential_name_len(targ_name);
 		if (targ_essent_len != local_essent_len)
 			continue;

 		if (strncmp(local_name, targ_name, local_essent_len) == 0) {
 			pr_debug("[%d] %s: found candidate [%d] %s\n",
 				 local_type_id, local_name, i, targ_name);
-			new_ids = realloc(cand_ids->data, cand_ids->len + 1);
+			new_ids = reallocarray(cand_ids->data,
+					       cand_ids->len + 1,
+					       sizeof(*cand_ids->data));
 			if (!new_ids) {
 				err = -ENOMEM;
 				goto err_out;
 			}
 			cand_ids->data = new_ids;
 			cand_ids->data[cand_ids->len++] = i;
 		}
 	}
 	return cand_ids;
 err_out:
 	bpf_core_free_cands(cand_ids);
 	return ERR_PTR(err);
 }



